          "type": "mol",
          "smiles": "C1COCCO1"
        },
        {
          "type": "mol",
          "smiles": "CC(=O)[C@]12CC=CC[C@H]1C(=O)C2"
        },
        {
          "type": "mol",
          "smiles": "O"
        }
      ]
    }
  ]
}
```

